{"implementation":"import json

def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    dists = case["distances"]
    edges = []
    for u, v, d in dists:
        mut = max(core[u], core[v], d)
        if u < v:
            edge = (u, v, mut)
        else:
            edge = (v, u, mut)
        edges.append(edge)
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Graph is disconnected")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
